UPDATE public.proposal_templates
SET blocks = jsonb_set(
  blocks,
  '{3,html}',
  to_jsonb($SLIDE$
<div style="box-sizing:border-box;width:100%;height:100%;max-width:100%;max-height:100%;margin:0;padding:44px 52px;border-radius:18px;overflow:hidden;border:1px solid #22c55e;box-shadow:0 0 0 1px rgba(34,197,94,.08),0 8px 24px -12px rgba(34,197,94,.25);font-family:Inter,system-ui,sans-serif;background:linear-gradient(180deg,#ffffff 0%,#f0fdf4 100%);color:#0f172a;display:flex;flex-direction:column;gap:22px;">
  <div style="display:grid;grid-template-columns:1.05fr .95fr;gap:28px;align-items:stretch;min-height:0;">
    <div style="display:flex;flex-direction:column;justify-content:center;min-width:0;">
      <div style="display:inline-flex;align-items:center;gap:6px;background:#16a34a;color:#fff;padding:6px 14px;border-radius:999px;font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;margin-bottom:14px;width:max-content;"><span style="width:6px;height:6px;border-radius:50%;background:#fff;opacity:.9;"></span>Impacto Operacional</div>
      <h2 style="font-size:34px;margin:0 0 14px;font-weight:900;color:#064e3b;letter-spacing:0;line-height:1.08;text-transform:uppercase;">Mais controle, previsibilidade e eficiência para sua operação de <span style="color:#16a34a;">vendas públicas.</span></h2>
      <div style="height:3px;width:64px;background:#22c55e;border-radius:3px;margin-bottom:16px;"></div>
      <p style="margin:0 0 10px;font-size:15px;line-height:1.55;color:#334155;">Ao estruturar informações, processos e acompanhamento operacional em uma única plataforma, empresas passam a operar com mais organização, visibilidade e melhor aproveitamento das oportunidades disponíveis no mercado público.</p>
      <p style="margin:0;font-size:15px;line-height:1.55;color:#334155;">O <span style="color:#16a34a;font-weight:800;">i-Ganhei</span> contribui para uma operação mais preparada para crescimento, tomada de decisão estratégica e evolução contínua da gestão comercial.</p>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;min-width:0;">
      <div style="display:flex;gap:12px;align-items:flex-start;padding:16px;background:#ffffff;border:1.5px solid #bbf7d0;border-radius:14px;box-shadow:0 6px 14px -8px rgba(34,197,94,.28);min-height:0;"><div style="width:42px;height:42px;border-radius:12px;border:2px solid #22c55e;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:#f0fdf4;"><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M7 14l4-4 4 4 5-6"/><path d="M16 8h4v4"/></svg></div><div style="min-width:0;"><div style="font-size:14px;font-weight:900;color:#064e3b;line-height:1.15;">Produtividade</div><div style="height:2px;width:28px;background:#22c55e;margin:7px 0;border-radius:2px;"></div><div style="font-size:12.5px;color:#475569;line-height:1.35;">Menos atividades manuais e retrabalho.</div></div></div>
      <div style="display:flex;gap:12px;align-items:flex-start;padding:16px;background:#ffffff;border:1.5px solid #bbf7d0;border-radius:14px;box-shadow:0 6px 14px -8px rgba(34,197,94,.28);min-height:0;"><div style="width:42px;height:42px;border-radius:12px;border:2px solid #22c55e;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:#f0fdf4;"><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/></svg></div><div style="min-width:0;"><div style="font-size:14px;font-weight:900;color:#064e3b;line-height:1.15;">Previsibilidade</div><div style="height:2px;width:28px;background:#22c55e;margin:7px 0;border-radius:2px;"></div><div style="font-size:12.5px;color:#475569;line-height:1.35;">Visão clara sobre oportunidades e evolução.</div></div></div>
      <div style="display:flex;gap:12px;align-items:flex-start;padding:16px;background:#ffffff;border:1.5px solid #bbf7d0;border-radius:14px;box-shadow:0 6px 14px -8px rgba(34,197,94,.28);min-height:0;"><div style="width:42px;height:42px;border-radius:12px;border:2px solid #22c55e;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:#f0fdf4;"><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3a4 4 0 0 0-4 4v1a3 3 0 0 0-2 5 3 3 0 0 0 2 5v1a4 4 0 0 0 8 0v-1a3 3 0 0 0 2-5 3 3 0 0 0-2-5V7a4 4 0 0 0-4-4z"/><path d="M12 8v8M9 11h6"/></svg></div><div style="min-width:0;"><div style="font-size:14px;font-weight:900;color:#064e3b;line-height:1.15;">Inteligência</div><div style="height:2px;width:28px;background:#22c55e;margin:7px 0;border-radius:2px;"></div><div style="font-size:12.5px;color:#475569;line-height:1.35;">Decisões orientadas por dados e indicadores.</div></div></div>
      <div style="display:flex;gap:12px;align-items:flex-start;padding:16px;background:#ffffff;border:1.5px solid #bbf7d0;border-radius:14px;box-shadow:0 6px 14px -8px rgba(34,197,94,.28);min-height:0;"><div style="width:42px;height:42px;border-radius:12px;border:2px solid #22c55e;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:#f0fdf4;"><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="9" cy="8" r="3"/><circle cx="17" cy="9" r="2.2"/><path d="M3 20c0-3 3-5 6-5s6 2 6 5"/><path d="M15 20c0-2 2-3.5 4-3.5s2.5 1 2.5 3"/></svg></div><div style="min-width:0;"><div style="font-size:14px;font-weight:900;color:#064e3b;line-height:1.15;">Escala</div><div style="height:2px;width:28px;background:#22c55e;margin:7px 0;border-radius:2px;"></div><div style="font-size:12.5px;color:#475569;line-height:1.35;">Operação mais organizada e eficiente.</div></div></div>
    </div>
  </div>
  <div style="padding:18px 20px;background:#ffffff;border:1.5px solid #bbf7d0;border-radius:16px;box-shadow:0 6px 14px -8px rgba(34,197,94,.28);min-height:0;">
    <div style="display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:16px;">
      <div style="display:flex;align-items:center;gap:12px;"><div style="width:38px;height:38px;border-radius:12px;border:2px solid #22c55e;background:#f0fdf4;display:flex;align-items:center;justify-content:center;flex-shrink:0;"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 21V5a2 2 0 0 1 2-2h7l5 5v13"/><path d="M14 3v5h5"/></svg></div><div><div style="font-size:16px;font-weight:900;color:#064e3b;line-height:1.15;">Acompanhamento completo da jornada</div><div style="font-size:12px;color:#475569;margin-top:2px;">Do mercado ao resultado, com controle e inteligência em cada etapa.</div></div></div>
      <div style="font-size:11px;font-weight:900;color:#16a34a;letter-spacing:.14em;text-transform:uppercase;white-space:nowrap;">Fluxo operacional</div>
    </div>
    <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:10px;align-items:stretch;">
      <div style="padding:12px 10px;border-radius:12px;background:#f0fdf4;border:1px solid #bbf7d0;text-align:center;min-width:0;"><div style="width:34px;height:34px;border-radius:10px;background:#16a34a;color:#fff;display:flex;align-items:center;justify-content:center;margin:0 auto 8px;font-size:12px;font-weight:900;">01</div><div style="font-size:12px;font-weight:900;color:#064e3b;line-height:1.18;">Inteligência de mercado</div><div style="font-size:10.5px;color:#475569;line-height:1.3;margin-top:5px;">Identificação assertiva das oportunidades.</div></div>
      <div style="padding:12px 10px;border-radius:12px;background:#f0fdf4;border:1px solid #bbf7d0;text-align:center;min-width:0;"><div style="width:34px;height:34px;border-radius:10px;background:#16a34a;color:#fff;display:flex;align-items:center;justify-content:center;margin:0 auto 8px;font-size:12px;font-weight:900;">02</div><div style="font-size:12px;font-weight:900;color:#064e3b;line-height:1.18;">Captação e análise</div><div style="font-size:10.5px;color:#475569;line-height:1.3;margin-top:5px;">Qualificação técnica e estratégica.</div></div>
      <div style="padding:12px 10px;border-radius:12px;background:#f0fdf4;border:1px solid #bbf7d0;text-align:center;min-width:0;"><div style="width:34px;height:34px;border-radius:10px;background:#16a34a;color:#fff;display:flex;align-items:center;justify-content:center;margin:0 auto 8px;font-size:12px;font-weight:900;">03</div><div style="font-size:12px;font-weight:900;color:#064e3b;line-height:1.18;">Documentos e proposta</div><div style="font-size:10.5px;color:#475569;line-height:1.3;margin-top:5px;">Organização, elaboração e envio.</div></div>
      <div style="padding:12px 10px;border-radius:12px;background:#f0fdf4;border:1px solid #bbf7d0;text-align:center;min-width:0;"><div style="width:34px;height:34px;border-radius:10px;background:#16a34a;color:#fff;display:flex;align-items:center;justify-content:center;margin:0 auto 8px;font-size:12px;font-weight:900;">04</div><div style="font-size:12px;font-weight:900;color:#064e3b;line-height:1.18;">Monitoramento</div><div style="font-size:10.5px;color:#475569;line-height:1.3;margin-top:5px;">Acompanhamento do certame e tratativas.</div></div>
      <div style="padding:12px 10px;border-radius:12px;background:#f0fdf4;border:1px solid #bbf7d0;text-align:center;min-width:0;"><div style="width:34px;height:34px;border-radius:10px;background:#16a34a;color:#fff;display:flex;align-items:center;justify-content:center;margin:0 auto 8px;font-size:12px;font-weight:900;">05</div><div style="font-size:12px;font-weight:900;color:#064e3b;line-height:1.18;">Contratação</div><div style="font-size:10.5px;color:#475569;line-height:1.3;margin-top:5px;">Formalização e análise dos resultados.</div></div>
    </div>
  </div>
</div>
$SLIDE$::text)
)
WHERE id = '9ac64afe-2213-4ceb-89c0-1bad0b83df87';